package org.apache.commons.compress.harmony.pack200;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.stream.IntStream;
import java.util.stream.Stream;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

/**
 * Tests for {@link CodecEncoding}: canonical codec lookup, arbitrary BHSD codec
 * decoding (specifier byte 116), run codec specifiers (117–140), and population
 * codec specifiers (141–188).
 */
class CodecEncodingTest {

    // Specifier byte ranges as defined by the Pack200 specification
    private static final int ARBITRARY_BHSD_SPECIFIER = 116;
    private static final int RUN_CODEC_SPECIFIER_MIN  = 117;
    private static final int RUN_CODEC_SPECIFIER_MAX  = 140;
    private static final int POP_CODEC_SPECIFIER_MIN  = 141;
    private static final int POP_CODEC_SPECIFIER_MAX  = 188;

    // ---------------------------------------------------------------------------
    // Parameterised test data
    // ---------------------------------------------------------------------------

    /**
     * Arbitrary BHSD codecs encoded via the two-byte extension header (specifier 116).
     * Each entry is (expectedToString, headerBytes).
     */
    static Stream<Arguments> arbitraryCodec() {
        return Stream.of(
            Arguments.of("(1,256)",     new byte[] { 0x00, (byte) 0xFF }),
            Arguments.of("(5,128,2,1)", new byte[] { 0x25, (byte) 0x7F }),
            Arguments.of("(2,128,1,1)", new byte[] { 0x0B, (byte) 0x7F })
        );
    }

    /**
     * The 115 canonical encodings defined by the Pack200 spec.
     * Each entry maps a single-byte specifier (1–115) to the expected codec string.
     */
    static Stream<Arguments> canonicalEncodings() {
        return Stream.of(
            // b=1
            Arguments.of(1,  "(1,256)"),    Arguments.of(2,  "(1,256,1)"),
            Arguments.of(3,  "(1,256,0,1)"), Arguments.of(4,  "(1,256,1,1)"),
            // b=2
            Arguments.of(5,  "(2,256)"),    Arguments.of(6,  "(2,256,1)"),
            Arguments.of(7,  "(2,256,0,1)"), Arguments.of(8,  "(2,256,1,1)"),
            // b=3
            Arguments.of(9,  "(3,256)"),    Arguments.of(10, "(3,256,1)"),
            Arguments.of(11, "(3,256,0,1)"), Arguments.of(12, "(3,256,1,1)"),
            // b=4
            Arguments.of(13, "(4,256)"),    Arguments.of(14, "(4,256,1)"),
            Arguments.of(15, "(4,256,0,1)"), Arguments.of(16, "(4,256,1,1)"),
            // b=5, h=4
            Arguments.of(17, "(5,4)"),   Arguments.of(18, "(5,4,1)"),   Arguments.of(19, "(5,4,2)"),
            // b=5, h=16
            Arguments.of(20, "(5,16)"),  Arguments.of(21, "(5,16,1)"),  Arguments.of(22, "(5,16,2)"),
            // b=5, h=32
            Arguments.of(23, "(5,32)"),  Arguments.of(24, "(5,32,1)"),  Arguments.of(25, "(5,32,2)"),
            // b=5, h=64
            Arguments.of(26, "(5,64)"),  Arguments.of(27, "(5,64,1)"),  Arguments.of(28, "(5,64,2)"),
            // b=5, h=128
            Arguments.of(29, "(5,128)"), Arguments.of(30, "(5,128,1)"), Arguments.of(31, "(5,128,2)"),
            // b=5, h=4, d=1
            Arguments.of(32, "(5,4,0,1)"),  Arguments.of(33, "(5,4,1,1)"),  Arguments.of(34, "(5,4,2,1)"),
            // b=5, h=16, d=1
            Arguments.of(35, "(5,16,0,1)"), Arguments.of(36, "(5,16,1,1)"), Arguments.of(37, "(5,16,2,1)"),
            // b=5, h=32, d=1
            Arguments.of(38, "(5,32,0,1)"), Arguments.of(39, "(5,32,1,1)"), Arguments.of(40, "(5,32,2,1)"),
            // b=5, h=64, d=1
            Arguments.of(41, "(5,64,0,1)"), Arguments.of(42, "(5,64,1,1)"), Arguments.of(43, "(5,64,2,1)"),
            // b=5, h=128, d=1
            Arguments.of(44, "(5,128,0,1)"), Arguments.of(45, "(5,128,1,1)"), Arguments.of(46, "(5,128,2,1)"),
            // b=2, high h
            Arguments.of(47, "(2,192)"), Arguments.of(48, "(2,224)"), Arguments.of(49, "(2,240)"),
            Arguments.of(50, "(2,248)"), Arguments.of(51, "(2,252)"),
            // b=2, low h, d=1
            Arguments.of(52, "(2,8,0,1)"),   Arguments.of(53, "(2,8,1,1)"),
            Arguments.of(54, "(2,16,0,1)"),  Arguments.of(55, "(2,16,1,1)"),
            Arguments.of(56, "(2,32,0,1)"),  Arguments.of(57, "(2,32,1,1)"),
            Arguments.of(58, "(2,64,0,1)"),  Arguments.of(59, "(2,64,1,1)"),
            Arguments.of(60, "(2,128,0,1)"), Arguments.of(61, "(2,128,1,1)"),
            Arguments.of(62, "(2,192,0,1)"), Arguments.of(63, "(2,192,1,1)"),
            Arguments.of(64, "(2,224,0,1)"), Arguments.of(65, "(2,224,1,1)"),
            Arguments.of(66, "(2,240,0,1)"), Arguments.of(67, "(2,240,1,1)"),
            Arguments.of(68, "(2,248,0,1)"), Arguments.of(69, "(2,248,1,1)"),
            // b=3, high h
            Arguments.of(70, "(3,192)"), Arguments.of(71, "(3,224)"), Arguments.of(72, "(3,240)"),
            Arguments.of(73, "(3,248)"), Arguments.of(74, "(3,252)"),
            // b=3, low h, d=1
            Arguments.of(75, "(3,8,0,1)"),   Arguments.of(76, "(3,8,1,1)"),
            Arguments.of(77, "(3,16,0,1)"),  Arguments.of(78, "(3,16,1,1)"),
            Arguments.of(79, "(3,32,0,1)"),  Arguments.of(80, "(3,32,1,1)"),
            Arguments.of(81, "(3,64,0,1)"),  Arguments.of(82, "(3,64,1,1)"),
            Arguments.of(83, "(3,128,0,1)"), Arguments.of(84, "(3,128,1,1)"),
            Arguments.of(85, "(3,192,0,1)"), Arguments.of(86, "(3,192,1,1)"),
            Arguments.of(87, "(3,224,0,1)"), Arguments.of(88, "(3,224,1,1)"),
            Arguments.of(89, "(3,240,0,1)"), Arguments.of(90, "(3,240,1,1)"),
            Arguments.of(91, "(3,248,0,1)"), Arguments.of(92, "(3,248,1,1)"),
            // b=4, high h
            Arguments.of(93, "(4,192)"), Arguments.of(94, "(4,224)"), Arguments.of(95, "(4,240)"),
            Arguments.of(96, "(4,248)"), Arguments.of(97, "(4,252)"),
            // b=4, low h, d=1
            Arguments.of(98,  "(4,8,0,1)"),   Arguments.of(99,  "(4,8,1,1)"),
            Arguments.of(100, "(4,16,0,1)"),  Arguments.of(101, "(4,16,1,1)"),
            Arguments.of(102, "(4,32,0,1)"),  Arguments.of(103, "(4,32,1,1)"),
            Arguments.of(104, "(4,64,0,1)"),  Arguments.of(105, "(4,64,1,1)"),
            Arguments.of(106, "(4,128,0,1)"), Arguments.of(107, "(4,128,1,1)"),
            Arguments.of(108, "(4,192,0,1)"), Arguments.of(109, "(4,192,1,1)"),
            Arguments.of(110, "(4,224,0,1)"), Arguments.of(111, "(4,224,1,1)"),
            Arguments.of(112, "(4,240,0,1)"), Arguments.of(113, "(4,240,1,1)"),
            Arguments.of(114, "(4,248,0,1)"), Arguments.of(115, "(4,248,1,1)")
        );
    }

    /** Canonical codec indices 1–114 for round-trip specifier tests. */
    static Stream<Arguments> canonicalGetSpecifier() {
        return IntStream.range(1, 115).mapToObj(Arguments::of);
    }

    /** Non-canonical BHSD codecs that must be encoded via the two-byte arbitrary header. */
    static Stream<Arguments> specifier() {
        return Stream.of(
            Arguments.of(new BHSDCodec(2, 125, 0, 1)),
            Arguments.of(new BHSDCodec(3, 125, 2, 1)),
            Arguments.of(new BHSDCodec(4, 125)),
            Arguments.of(new BHSDCodec(5, 125, 2, 0)),
            Arguments.of(new BHSDCodec(3, 5, 2, 1))
        );
    }

    // ---------------------------------------------------------------------------
    // Helper methods
    // ---------------------------------------------------------------------------

    /**
     * Converts the tail of a specifier array (indices 1 onward) into a byte
     * {@link InputStream} suitable for passing to {@link CodecEncoding#getCodec}.
     * The first element of {@code specifiers} is the leading type byte and is
     * not included in the stream.
     */
    private static InputStream tailSpecifiersToStream(final int[] specifiers) {
        final byte[] bytes = new byte[specifiers.length - 1];
        for (int i = 0; i < bytes.length; i++) {
            bytes[i] = (byte) specifiers[i + 1];
        }
        return new ByteArrayInputStream(bytes);
    }

    // ---------------------------------------------------------------------------
    // Tests
    // ---------------------------------------------------------------------------

    @ParameterizedTest
    @DisplayName("Arbitrary BHSD codec decoded from two-byte extension header (specifier 116)")
    @MethodSource("arbitraryCodec")
    void testArbitraryCodec(final String expected, final byte[] bytes) throws IOException, Pack200Exception {
        assertEquals(expected, CodecEncoding.getCodec(116, new ByteArrayInputStream(bytes), null).toString());
    }

    @ParameterizedTest
    @DisplayName("Canonical codecs 1–115 decoded by their single-byte specifier")
    @MethodSource("canonicalEncodings")
    void testCanonicalEncodings(final int i, final String expectedCodec) throws IOException, Pack200Exception {
        assertEquals(expectedCodec, CodecEncoding.getCodec(i, null, null).toString());
    }

    @ParameterizedTest
    @DisplayName("getSpecifier round-trips canonical codecs: specifier[0] equals original index")
    @MethodSource("canonicalGetSpecifier")
    void testCanonicalGetSpecifier(final int i) throws Pack200Exception, IOException {
        assertEquals(i, CodecEncoding.getSpecifier(CodecEncoding.getCodec(i, null, null), null)[0]);
    }

    @Test
    @DisplayName("Specifier 0 returns the supplied default codec")
    void testDefaultCodec() throws Pack200Exception, IOException {
        final Codec defaultCodec = new BHSDCodec(2, 16, 0, 0);
        assertEquals(defaultCodec, CodecEncoding.getCodec(0, null, defaultCodec));
    }

    @Test
    @DisplayName("getSpecifier for PopulationCodec produces a specifier in the population range (141–188)")
    void testGetSpecifierForPopulationCodec() throws IOException, Pack200Exception {
        final PopulationCodec populationCodec = new PopulationCodec(Codec.BYTE1, Codec.CHAR3, Codec.UNSIGNED5);
        final int[] specifiers = CodecEncoding.getSpecifier(populationCodec, null);
        assertTrue(specifiers[0] > POP_CODEC_SPECIFIER_MIN - 1);
        assertTrue(specifiers[0] < POP_CODEC_SPECIFIER_MAX + 1);

        final PopulationCodec decoded =
            (PopulationCodec) CodecEncoding.getCodec(specifiers[0], tailSpecifiersToStream(specifiers), null);
        assertEquals(populationCodec.getFavouredCodec(),    decoded.getFavouredCodec());
        assertEquals(populationCodec.getTokenCodec(),       decoded.getTokenCodec());
        assertEquals(populationCodec.getUnfavouredCodec(), decoded.getUnfavouredCodec());
    }

    @Test
    @DisplayName("getSpecifier for a simple RunCodec produces a specifier in the run range (117–140)")
    void testGetSpecifierForSimpleRunCodec() throws Pack200Exception, IOException {
        final RunCodec runCodec = new RunCodec(25, Codec.DELTA5, Codec.BYTE1);
        final int[] specifiers = CodecEncoding.getSpecifier(runCodec, null);
        assertTrue(specifiers[0] > RUN_CODEC_SPECIFIER_MIN - 1);
        assertTrue(specifiers[0] < RUN_CODEC_SPECIFIER_MAX + 1);

        final RunCodec decoded =
            (RunCodec) CodecEncoding.getCodec(specifiers[0], tailSpecifiersToStream(specifiers), null);
        assertEquals(runCodec.getK(),       decoded.getK());
        assertEquals(runCodec.getACodec(), decoded.getACodec());
        assertEquals(runCodec.getBCodec(), decoded.getBCodec());
    }

    @Test
    @DisplayName("getSpecifier for a RunCodec where one sub-codec equals the band default")
    void testGetSpecifierForRunCodecWithDefaultCodec() throws Pack200Exception, IOException {
        final RunCodec runCodec = new RunCodec(4096, Codec.DELTA5, Codec.BYTE1);
        final int[] specifiers = CodecEncoding.getSpecifier(runCodec, Codec.DELTA5);
        assertTrue(specifiers[0] > RUN_CODEC_SPECIFIER_MIN - 1);
        assertTrue(specifiers[0] < RUN_CODEC_SPECIFIER_MAX + 1);

        final RunCodec decoded =
            (RunCodec) CodecEncoding.getCodec(specifiers[0], tailSpecifiersToStream(specifiers), Codec.DELTA5);
        assertEquals(runCodec.getK(),       decoded.getK());
        assertEquals(runCodec.getACodec(), decoded.getACodec());
        assertEquals(runCodec.getBCodec(), decoded.getBCodec());
    }

    @Test
    @DisplayName("getSpecifier for a nested RunCodec (run inside run)")
    void testGetSpecifierForNestedRunCodec() throws Pack200Exception, IOException {
        final RunCodec runCodec = new RunCodec(64, Codec.SIGNED5, new RunCodec(25, Codec.UDELTA5, Codec.DELTA5));
        final int[] specifiers = CodecEncoding.getSpecifier(runCodec, null);
        assertTrue(specifiers[0] > RUN_CODEC_SPECIFIER_MIN - 1);
        assertTrue(specifiers[0] < RUN_CODEC_SPECIFIER_MAX + 1);

        final RunCodec decoded =
            (RunCodec) CodecEncoding.getCodec(specifiers[0], tailSpecifiersToStream(specifiers), null);
        assertEquals(runCodec.getK(),       decoded.getK());
        assertEquals(runCodec.getACodec(), decoded.getACodec());

        final RunCodec innerOriginal = (RunCodec) runCodec.getBCodec();
        final RunCodec innerDecoded  = (RunCodec) decoded.getBCodec();
        assertEquals(innerOriginal.getK(),       innerDecoded.getK());
        assertEquals(innerOriginal.getACodec(), innerDecoded.getACodec());
        assertEquals(innerOriginal.getBCodec(), innerDecoded.getBCodec());
    }

    @Test
    @DisplayName("getSpecifier for a nested RunCodec where the inner sub-codec equals the band default")
    void testGetSpecifierForNestedRunCodecWithDefaultCodec() throws Pack200Exception, IOException {
        final RunCodec runCodec = new RunCodec(64, Codec.SIGNED5, new RunCodec(25, Codec.UDELTA5, Codec.DELTA5));
        final int[] specifiers = CodecEncoding.getSpecifier(runCodec, Codec.UDELTA5);
        assertTrue(specifiers[0] > RUN_CODEC_SPECIFIER_MIN - 1);
        assertTrue(specifiers[0] < RUN_CODEC_SPECIFIER_MAX + 1);

        final RunCodec decoded =
            (RunCodec) CodecEncoding.getCodec(specifiers[0], tailSpecifiersToStream(specifiers), Codec.UDELTA5);
        assertEquals(runCodec.getK(),       decoded.getK());
        assertEquals(runCodec.getACodec(), decoded.getACodec());

        final RunCodec innerOriginal = (RunCodec) runCodec.getBCodec();
        final RunCodec innerDecoded  = (RunCodec) decoded.getBCodec();
        assertEquals(innerOriginal.getK(),       innerDecoded.getK());
        assertEquals(innerOriginal.getACodec(), innerDecoded.getACodec());
        assertEquals(innerOriginal.getBCodec(), innerDecoded.getBCodec());
    }

    @ParameterizedTest
    @DisplayName("getSpecifier for non-canonical BHSD codec uses two-byte arbitrary header (specifier 116)")
    @MethodSource("specifier")
    void testGetSpecifier(final Codec c1) throws IOException, Pack200Exception {
        final int[] specifiers = CodecEncoding.getSpecifier(c1, null);
        assertEquals(3, specifiers.length);
        assertEquals(ARBITRARY_BHSD_SPECIFIER, specifiers[0]);
        final byte[] bytes = { (byte) specifiers[1], (byte) specifiers[2] };
        final InputStream in = new ByteArrayInputStream(bytes);
        assertEquals(c1, CodecEncoding.getCodec(ARBITRARY_BHSD_SPECIFIER, in, null));
    }
}
